import type * as Phaser from 'phaser';
import { getLocale, t } from '../../i18n';
import { getOverlayRoot } from '../fullscreen';
import { appendForestDialogClose, applyForestDialogTheme } from '../ForestModal';
import { activateUi, playUiActivation } from '../UiAudio';
import {
  CONTROL_ACTIONS,
  isControlBindingAllowed,
  type ControlActionGroup,
  type ControlActionId,
  type ControlBinding,
  type ControlMouseButton,
} from '../../controls/controlBindings';
import {
  getControlBinding,
  getControlKeyLabel,
  resetControlBindings,
  setControlBinding,
} from '../../controls/controlBindingStore';
import { formatControlBindingLabel, needsCapturedKeyLabel } from '../../controls/controlKeyLabels';
import '../ProfileDialog.css';
import './KeyBindingsDialog.css';

/** Design size of the wooden frame; the CSS clamps the dialog to the viewport. */
const FRAME_W = 980;
const FRAME_H = 740;

/** Captured DOM events must not reach Phaser or game hotkeys while the native modal is open. */
const ISOLATED_EVENTS = ['pointerdown', 'pointerup', 'pointermove', 'mousedown', 'mouseup', 'mousemove', 'click',
  'dblclick', 'wheel', 'touchstart', 'touchend', 'touchmove', 'keydown', 'keyup', 'contextmenu'] as const;

const ASSIGNABLE_MOUSE_BUTTONS: ReadonlySet<number> = new Set([1, 3, 4]);
const GROUP_LABELS: Readonly<Record<ControlActionGroup, string>> = {
  movement: 'ui.controls.group.movement',
  actions: 'ui.controls.group.actions',
  interface: 'ui.controls.group.interface',
};
const FIXED_ROWS: readonly { readonly labelKey: string; readonly inputKey: string; readonly hintKey?: string }[] = [
  { labelKey: 'ui.controls.fixed.weapon1', inputKey: 'ui.keys.mouseLeft', hintKey: 'ui.controls.hint.weapon1' },
  { labelKey: 'ui.controls.fixed.weapon2', inputKey: 'ui.keys.mouseRight', hintKey: 'ui.controls.hint.weapon2' },
  { labelKey: 'ui.controls.fixed.menu', inputKey: 'ui.keys.escape' },
  { labelKey: 'ui.controls.fixed.zoom', inputKey: 'ui.keys.wheel' },
];
/**
 * Spielhinweise direkt bei der jeweiligen Taste; sie ersetzen das fruehere Hilfe-Fenster.
 * Bewegung und Dash erklaeren sich selbst und bleiben ohne Hinweis.
 */
const ACTION_HINT_KEYS: Readonly<Partial<Record<ControlActionId, string>>> = {
  interact: 'ui.controls.hint.interact',
  utility: 'ui.controls.hint.utility',
  utilityWheel: 'ui.controls.hint.utilityWheel',
  ultimate: 'ui.controls.hint.ultimate',
  arenaPanel: 'ui.controls.hint.arenaPanel',
};

let openDialog: { close: () => void } | null = null;

function element<K extends keyof HTMLElementTagNameMap>(tag: K, text?: string, className?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

/** Bezeichnung der Zeile, darunter optional der gedaempfte Spielhinweis. */
function rowLabel(text: string, id: string, hintKey: string | undefined): HTMLElement {
  const cell = element('div', undefined, 'keybindings-label');
  const label = element('span', text);
  label.id = id;
  cell.append(label);
  if (hintKey) {
    const hint = element('span', t(hintKey), 'keybindings-hint');
    hint.id = `${id}-hint`;
    cell.append(hint);
  }
  return cell;
}

function actionLabel(action: ControlActionId): string {
  return t(CONTROL_ACTIONS.find((entry) => entry.id === action)!.labelKey);
}

/** Belegung aus einem Tastendruck; Satzzeichen-Tasten merken sich das Zeichen des Layouts. */
function bindingFromKeyboard(event: KeyboardEvent): ControlBinding {
  const label = needsCapturedKeyLabel(event.keyCode) && event.key.length === 1 ? event.key : undefined;
  return label ? { device: 'key', code: event.keyCode, label } : { device: 'key', code: event.keyCode };
}

/**
 * Opens the key binding editor as a native modal dialog above the options overlay. Loaded on
 * demand, so neither this module nor its stylesheet are part of the boot path. Every change goes
 * straight to the binding store: it is saved on this device and applies in the game immediately.
 */
export function openKeyBindingsDialog(scene: Phaser.Scene, onClosed?: () => void): void {
  if (openDialog) return;
  const dialog = element('dialog', undefined, 'player-profile keybindings-dialog');
  dialog.setAttribute('aria-labelledby', 'keybindings-title');
  applyForestDialogTheme(scene, dialog, FRAME_W, FRAME_H);

  const title = element('h2', t('ui.controls.title'));
  title.id = 'keybindings-title';
  const body = element('div', undefined, 'keybindings-body');
  const keyButtons = new Map<ControlActionId, HTMLButtonElement>();
  let capturing: ControlActionId | null = null;
  const flashTimers = new Map<HTMLButtonElement, number>();

  /**
   * Rueckmeldung direkt am Knopf statt in einer Statuszeile: kurzes Aufleuchten bei einem Tausch,
   * rotes bei einer abgelehnten Eingabe. Der Grund steht als Tooltip am Knopf.
   */
  const flash = (button: HTMLButtonElement | undefined, kind: 'swap' | 'reject', reason: string) => {
    if (!button) return;
    window.clearTimeout(flashTimers.get(button));
    button.classList.remove('is-flash', 'is-rejected');
    void button.offsetWidth; // restart the CSS animation
    button.classList.add(kind === 'swap' ? 'is-flash' : 'is-rejected');
    button.title = reason;
    flashTimers.set(button, window.setTimeout(() => {
      button.classList.remove('is-flash', 'is-rejected');
      flashTimers.delete(button);
    }, 1200));
  };

  const renderKeys = () => {
    for (const [action, button] of keyButtons) {
      const unbound = getControlBinding(action) === null;
      button.textContent = action === capturing ? t('ui.controls.capturing') : getControlKeyLabel(action);
      button.classList.toggle('is-capturing', action === capturing);
      button.classList.toggle('is-unbound', unbound && action !== capturing);
      button.title = unbound ? t('ui.controls.unbound') : '';
      button.setAttribute('aria-pressed', String(action === capturing));
    }
  };

  const stopCapture = () => {
    capturing = null;
    renderKeys();
  };

  const startCapture = (action: ControlActionId) => {
    capturing = action;
    renderKeys();
  };

  const assign = (binding: ControlBinding) => {
    const action = capturing;
    if (!action) return;
    capturing = null;
    const reserved = t('ui.controls.reserved', { key: formatControlBindingLabel(binding, getLocale()) });
    const result = isControlBindingAllowed(binding) ? setControlBinding(action, binding) : null;
    renderKeys();
    if (!result?.ok) {
      flash(keyButtons.get(action), 'reject', reserved);
    } else {
      playUiActivation(scene);
      if (result.swappedWith) {
        const swapped = t('ui.controls.swapped', { action: actionLabel(result.swappedWith) });
        flash(keyButtons.get(action), 'swap', swapped);
        flash(keyButtons.get(result.swappedWith), 'swap', swapped);
      }
    }
    keyButtons.get(action)?.focus();
  };

  // Zwei Spalten, damit alle Zeilen ohne Scrollen sichtbar sind: links Bewegung und Oberflaeche,
  // rechts Aktionen und die festen Eingaben.
  const columns = { left: element('div', undefined, 'keybindings-column'), right: element('div', undefined, 'keybindings-column') };
  const columnOf: Readonly<Record<ControlActionGroup, HTMLElement>> = {
    movement: columns.left, interface: columns.left, actions: columns.right,
  };
  for (const group of ['movement', 'interface', 'actions'] as const) {
    const section = element('section');
    const list = element('ul');
    for (const action of CONTROL_ACTIONS.filter((entry) => entry.group === group)) {
      const row = element('li');
      const hintKey = ACTION_HINT_KEYS[action.id];
      const labelId = `keybindings-label-${action.id}`;
      const label = rowLabel(t(action.labelKey), labelId, hintKey);
      const button = element('button', '', 'keybindings-key');
      button.type = 'button';
      button.setAttribute('aria-describedby', hintKey ? `${labelId} ${labelId}-hint` : labelId);
      button.onclick = () => activateUi(scene, () => {
        if (capturing === action.id) stopCapture();
        else startCapture(action.id);
      });
      keyButtons.set(action.id, button);
      row.append(label, button);
      list.append(row);
    }
    section.append(element('h3', t(GROUP_LABELS[group])), list);
    columnOf[group].append(section);
  }
  const fixed = element('section', undefined, 'keybindings-fixed');
  const fixedList = element('ul');
  for (const [index, row] of FIXED_ROWS.entries()) {
    const item = element('li');
    item.append(rowLabel(t(row.labelKey), `keybindings-fixed-${index}`, row.hintKey),
      element('span', t(row.inputKey), 'keybindings-key is-fixed'));
    fixedList.append(item);
  }
  fixed.append(element('h3', t('ui.controls.group.fixed')), fixedList);
  columns.right.append(fixed);
  body.append(columns.left, columns.right);

  const actions = element('div', undefined, 'profile-actions');
  const resetButton = element('button', t('ui.controls.reset'));
  resetButton.type = 'button';
  actions.append(resetButton);
  dialog.append(title, body, actions);
  renderKeys();

  const inputEnabled = scene.input.enabled;
  scene.input.enabled = false;
  for (const type of ISOLATED_EVENTS) dialog.addEventListener(type, event => event.stopPropagation());

  dialog.addEventListener('keydown', (event) => {
    if (!capturing) return;
    event.preventDefault();
    if (event.repeat) return;
    if (event.key === 'Escape') {
      stopCapture();
      return;
    }
    assign(bindingFromKeyboard(event));
  });
  dialog.addEventListener('mousedown', (event) => {
    if (!capturing) return;
    if (ASSIGNABLE_MOUSE_BUTTONS.has(event.button)) {
      event.preventDefault();
      assign({ device: 'mouse', button: event.button as ControlMouseButton });
      return;
    }
    if (event.button === 2) {
      event.preventDefault();
      const action = capturing;
      stopCapture();
      flash(keyButtons.get(action), 'reject', t('ui.controls.reserved', { key: t('ui.keys.mouseRight') }));
      return;
    }
    // A left click on a binding button restarts the capture there; anywhere else ends it.
    if (!(event.target instanceof HTMLElement && event.target.classList.contains('keybindings-key'))) {
      stopCapture();
    }
  });
  // Side buttons would navigate back/forward and the middle button would start autoscrolling.
  const suppressMouseDefault = (event: MouseEvent) => {
    if (ASSIGNABLE_MOUSE_BUTTONS.has(event.button)) event.preventDefault();
  };
  dialog.addEventListener('mouseup', suppressMouseDefault);
  dialog.addEventListener('auxclick', suppressMouseDefault);
  dialog.addEventListener('contextmenu', event => event.preventDefault());

  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    for (const timer of flashTimers.values()) window.clearTimeout(timer);
    if (openDialog?.close === close) openDialog = null;
    scene.events.off('shutdown', close);
    dialog.close();
    dialog.remove();
    // Releases may have happened inside the DOM dialog; do not keep a held game pointer.
    scene.input.activePointer?.reset();
    scene.input.enabled = inputEnabled;
    onClosed?.();
  };
  openDialog = { close };
  scene.events.once('shutdown', close);
  const closeButton = appendForestDialogClose(scene, dialog, FRAME_W, FRAME_H, close);
  resetButton.onclick = () => activateUi(scene, () => {
    capturing = null;
    resetControlBindings();
    renderKeys();
  });
  dialog.addEventListener('cancel', (event) => {
    event.preventDefault();
    // Esc while capturing only ends the capture; otherwise it closes the dialog.
    if (capturing) {
      stopCapture();
      return;
    }
    close();
  });

  getOverlayRoot().appendChild(dialog);
  dialog.showModal();
  closeButton.focus();
}
